/* The shapes of live_data.h (generated by tools/gen.py). */
#pragma once
#include <stdint.h>
#include <stddef.h>

/* A reference in a record or row to content the mod adds at run time: the u32 at `offset` becomes the id HellForge gave
 * the mod's copy of live projectile (kind 1) or damage (kind 2) number `index` (an index into live_projectiles /
 * live_damage). A list ends with offset 0 and kind 0. */
typedef struct LiveFix
{
    uint32_t offset;
    uint32_t kind;
    uint32_t index;
} LiveFix;
enum { LIVE_FIX_PROJECTILE = 1, LIVE_FIX_DAMAGE = 2 };

/* Bytes of a record that stay as HellForge made them (a list ends with length 0). */
typedef struct LiveKeep
{
    uint32_t offset;
    uint32_t length;
} LiveKeep;

/* A component table as the vanilla entity data has it (see gen.py, windows()). */
typedef struct LiveTable
{
    const char* component;
    uint32_t slots;            /* index entries (16 bytes: resource, record index, padding) */
    uint32_t records;          /* vanilla records; HellForge's copy has room for `slots` */
    uint32_t record_offset;    /* from the table's start to its first record */
    uint32_t stride;
    uint32_t window_at[2];     /* where in the index each window is */
    uint8_t window[2][32];     /* two runs of the vanilla index, each unique in the entity data */
} LiveTable;

/* One component record of a live entity, in the pinned build's layout: `live` is what the live game has (enum values
 * renumbered, abilities the pinned build lacks replaced by their donors'), `base` the base entity's record in the pinned
 * build's own data. Where the copy's record differs from `base` when the mod writes it, HellForge (or a stats mod) set
 * that byte, and it is kept. */
typedef struct LiveRecord
{
    const char* component;
    uint32_t size;
    const uint8_t* live;
    const uint8_t* base;
    const LiveFix* fixes;
    const LiveKeep* keep;
    const LiveTable* table;
    uint32_t base_index;       /* the base's record in the vanilla table */
} LiveRecord;

/* A settings row the live weapons use that the pinned build lacks: a copy of `base` (a vanilla id), then the live row
 * written over it (all but its +0 id). */
typedef struct LiveRow
{
    uint32_t live_id;
    uint32_t base;
    const uint8_t* row;
    uint32_t size;
    const LiveFix* fixes;
} LiveRow;

/* A live entity under its live name (so its resource id, and a weapon's loadout id, are the live game's). */
typedef struct LiveEntity
{
    const char* key;
    const char* name;          /* the live entity (and unit) resource name */
    uint64_t base;             /* the pinned build's entity it is a copy of */
    uint32_t base_item;        /* for an arsenal weapon, the base's loadout id (add_weapon); 0 for an entity */
    const char* designation;
    const char* title;
    const char* description;
    const LiveRecord* records; /* ends with component NULL */
    uint64_t entity;           /* set at run time: its resource id */
    uint32_t item;             /* set at run time: an arsenal weapon's loadout id */
} LiveEntity;
